/**
 * LiquidThemeToggle - Premium Apple-Inspired Dark/Light Mode Toggle
 * Features:
 * - Liquid morphing knob with spring animation
 * - Smooth icon transitions
 * - Glassmorphic design
 * - Fully accessible
 * - Production-ready
 */

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../context/useTheme';

const LiquidThemeToggle = () => {
  const { isDark, toggleTheme } = useTheme();

  // Spring animation config for iOS-like feel
  const springConfig = {
    type: 'spring',
    stiffness: 300,
    damping: 20,
    mass: 0.9,
  };

  // Knob animation variants
  const knobVariants = {
    light: {
      x: 0,
      transition: springConfig,
    },
    dark: {
      x: 24,
      transition: springConfig,
    },
  };

  // Stretch effect while moving
  const scaleVariants = {
    light: {
      scaleX: 1,
      transition: { ...springConfig, stiffness: 400 },
    },
    dark: {
      scaleX: 1,
      transition: { ...springConfig, stiffness: 400 },
    },
  };

  // Icon animation variants
  const iconVariants = {
    enter: {
      opacity: 0,
      rotate: -180,
      scale: 0.5,
    },
    center: {
      opacity: 1,
      rotate: 0,
      scale: 1,
    },
    exit: {
      opacity: 0,
      rotate: 180,
      scale: 0.5,
    },
  };

  return (
    <motion.button
      onClick={toggleTheme}
      className="relative w-14 h-8 rounded-full bg-gradient-to-r from-gray-200 via-gray-100 to-gray-200 dark:from-gray-700 dark:via-gray-800 dark:to-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900 transition-all duration-300"
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.98 }}
      initial={false}
      aria-label={`Switch to ${isDark ? 'light' : 'dark'} mode`}
      aria-pressed={isDark}
      style={{
        boxShadow: isDark
          ? 'inset 0 2px 8px rgba(0, 0, 0, 0.3), 0 0 20px rgba(59, 130, 246, 0.15)'
          : 'inset 0 2px 8px rgba(0, 0, 0, 0.05), 0 0 12px rgba(59, 130, 246, 0.1)',
      }}
    >
      {/* Background glow in dark mode */}
      {isDark && (
        <motion.div
          className="absolute inset-0 bg-blue-500 rounded-full opacity-0 blur-md"
          animate={{ opacity: 0.1 }}
          transition={{ duration: 0.5 }}
          initial={false}
        />
      )}

      {/* Animated knob */}
      <motion.div
        className="absolute top-1 left-1 w-6 h-6 rounded-full bg-gradient-to-br from-white to-gray-50 dark:from-gray-600 dark:to-gray-700 shadow-lg flex items-center justify-center"
        animate={isDark ? 'dark' : 'light'}
        variants={knobVariants}
        style={{
          boxShadow: isDark
            ? '0 4px 12px rgba(0, 0, 0, 0.3), inset 0 1px 2px rgba(255, 255, 255, 0.1)'
            : '0 4px 12px rgba(0, 0, 0, 0.15), inset 0 1px 2px rgba(255, 255, 255, 0.5)',
        }}
      >
        {/* Icons with smooth transition */}
        <AnimatePresence mode="wait" initial={false}>
          {isDark ? (
            <motion.div
              key="moon"
              variants={iconVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{ duration: 0.3 }}
              className="absolute text-yellow-300 text-sm"
            >
              🌙
            </motion.div>
          ) : (
            <motion.div
              key="sun"
              variants={iconVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{ duration: 0.3 }}
              className="absolute text-yellow-500 text-sm"
            >
              ☀️
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>

      {/* Shimmer effect on toggle */}
      <motion.div
        className="absolute inset-0 rounded-full opacity-0"
        animate={isDark ? { opacity: 0 } : { opacity: 0 }}
        transition={{ duration: 0.3 }}
        style={{
          background: isDark
            ? 'linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.1), transparent)'
            : 'linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent)',
          pointerEvents: 'none',
        }}
      />
    </motion.button>
  );
};

export default LiquidThemeToggle;
